/* forward declarations of stuff generated by lemon */

#define RSQuery_Parse_v2 RSQueryParser_v2_ // weird Lemon quirk.. oh well..
#define RSQuery_ParseAlloc_v2 RSQueryParser_v2_Alloc
#define RSQuery_ParseFree_v2 RSQueryParser_v2_Free

void RSQuery_Parse_v2(void *yyp, int yymajor, QueryToken yyminor, QueryParseCtx *ctx);
void *RSQuery_ParseAlloc_v2(void *(*mallocProc)(size_t));
void RSQuery_ParseFree_v2(void *p, void (*freeProc)(void *));

int RSQuery_ParseNumericOp_v2(void* pParser, int OperatorType, QueryToken tok,
      QueryParseCtx *q, const char *ts, const char *te, char c1,
      unsigned int opLen) {
    tok.len = te - (ts + 1);
    tok.pos = ts - q->raw;
    tok.s = ts + 1;

    // Find the position before the operator
    const char *end1 = strchr(tok.s, c1) - 1;
    // Find the position after the operator
    const char *start2 = end1 + opLen + 1;
    // Remove unescaped spaces at the end of the modifier
    const char *m = tok.s;
    int escaped = (*m == '\\');
    while (m < end1) {
      if (isspace(*(m + 1)) && !escaped) {
        end1 = m;
        break;
      }
      ++m;
      escaped = !escaped && *m == '\\';
    }
    tok.len = end1 - tok.s + 1;
    RSQuery_Parse_v2(pParser, MODIFIER, tok, q);
    if (!QPCTX_ISOK(q)) {
      return 0;
    }

    tok.s = start2 - opLen;
    tok.len = opLen;
    RSQuery_Parse_v2(pParser, OperatorType, tok, q);
    if (!QPCTX_ISOK(q)) {
      return 0;
    }

    // Remove spaces after the operator
    while (isspace(*start2)) {
      ++start2;
    }

    // Detect parameter's sign if exists
    if ((*start2 == '+' || *start2 == '-') && *(start2+1) == '$') {
      tok.sign = *start2 == '-' ? -1 : 1;
      ++start2;
    }
    tok.s = start2;
    int is_attr = (*(tok.s) == '$') ? 1 : 0;
    tok.len = (te - start2) + 1 - is_attr;

    if(is_attr) {
      tok.s++;
      // Remove trailing spaces from attribute
      while (isspace(*(tok.s + tok.len - 1))) {
        --tok.len;
      }
      RSQuery_Parse_v2(pParser, ATTRIBUTE, tok, q);
    } else {
      char *ne = (char*)te;
      tok.numval = fast_float_strtod(tok.s, &ne);
      RSQuery_Parse_v2(pParser, NUMBER, tok, q);
    }
    if (!QPCTX_ISOK(q)) {
        return 0;
    }
    return 1;
}

/* Emit a field-scoped comparison - `@field:<op>` - as the three tokens
 * `MODIFIER COLON <OperatorType>`.
 *
 * `ts` points at the '@', `te` one past the operator's last character, and
 * `opLen` is the operator's length (1 for `<`/`>`, 2 for `<=`/`>=`).
 *
 * The single ENABLE_UNSTABLE_FEATURES gate for this syntax; the shard-local and
 * coordinator parses both come through here. With the flag off the query is
 * rejected rather than parsed as the pre-feature `@field:(v)`, which would
 * answer a client that reached for the operator with a wrong result set. */
int RSQuery_ParseFieldColonOp_v2(void *pParser, int OperatorType, QueryToken tok,
      QueryParseCtx *q, const char *ts, const char *te, unsigned int opLen) {
    const char *name = ts + 1;

    // Find the ':' separating the name from the operator, tracking escapes: a
    // name may contain an escaped ':' (`@a\:b`) or an escaped space, while the
    // unescaped spaces the pattern allows before the ':' are not part of it.
    // Bounded by `te` since the ':' is inside the matched text, so this never
    // depends on the query buffer being NUL-terminated.
    const char *p = name;
    const char *nameEnd = name;
    int escaped = 0;
    while (p < te) {
      if (!escaped && *p == ':') {
        break;
      }
      if (!escaped && *p == '\\') {
        escaped = 1;
        ++p;
        continue;
      }
      if (escaped || !isspace((unsigned char)*p)) {
        nameEnd = p + 1;
      }
      escaped = 0;
      ++p;
    }
    const char *colon = p;

    tok.type = QT_TERM;
    tok.pos = ts - q->raw;
    tok.s = name;
    tok.len = nameEnd - name;
    RSQuery_Parse_v2(pParser, MODIFIER, tok, q);
    if (!QPCTX_ISOK(q)) {
      return 0;
    }

    tok.pos = colon - q->raw;
    tok.s = colon;
    tok.len = 1;
    RSQuery_Parse_v2(pParser, COLON, tok, q);
    if (!QPCTX_ISOK(q)) {
      return 0;
    }

    // Requirement 1 of docs/CONTRIBUTING-unstable-features.md: with the flag off
    // an existing query keeps its results and its errors. `@f:>{v}` already
    // parses - `>` is punctuation the lexer drops, leaving the tag clause
    // `@f:{v}` - so rejecting it here would change what a user who never
    // enabled the feature gets back. Leave the operator unemitted and let that
    // parse stand. Checking before the scan below also keeps the flag-off cost
    // to the one branch Requirement 4 asks for.
    if (!RSGlobalConfig.enableUnstableFeatures) {
      return 1;
    }

    // The operator only means a lex range when a brace bound follows it. `@f:>`
    // alone, or followed by anything else, keeps parsing as it did before this
    // syntax existed.
    const char *after = te;
    const char *queryEnd = q->raw + q->len;
    while (after < queryEnd && isspace((unsigned char)*after)) {
      ++after;
    }
    if (after == queryEnd || *after != '{') {
      return 1;
    }

    tok.pos = (te - opLen) - q->raw;
    tok.s = te - opLen;
    tok.len = opLen;
    RSQuery_Parse_v2(pParser, OperatorType, tok, q);
    if (!QPCTX_ISOK(q)) {
      return 0;
    }
    return 1;
}


